function [h] = hloc_of(hl)
%HLOC_OF  The local-time harmonics at a local solar time [rad].
%   hl: real[1] (passed a plain number)
%   returns h: Hloc (passed rec)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    h = asils.models.dtm2020.Hloc_zero();
    h = asils.models.dtm2020.Hloc_zero();
    h.ch = cos(hl);
    h.sh = sin(hl);
    h__187 = (h.ch)^(2);
    if ~isreal(h__187), h__187 = NaN; end
    h__188 = (h.sh)^(2);
    if ~isreal(h__188), h__188 = NaN; end
    h.c2h = (h__187 - h__188);
    h.s2h = ((2 * h.ch) * h.sh);
    h.c3h = ((h.c2h * h.ch) - (h.s2h * h.sh));
    h.s3h = ((h.s2h * h.ch) + (h.c2h * h.sh));
end
